"""Build the physical research pack, then apply verified source updates.
Run from repository root: python research/scripts/physical-complete.py
No network needed; checked facts and the selected Waymo CSV extract are inputs.
"""
import runpy,json,pathlib,hashlib
G=runpy.run_path(str(pathlib.Path(__file__).with_name('physical-build.py')))
BASE,D,S,NOW,row,dataset,source=[G[k] for k in ('BASE','D','S','NOW','row','dataset','source')]
def write(d):
 (BASE/'datasets'/f"{d['datasetId']}.json").write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
# Versioned CSV replaces dashboard point estimates. Source release notes explicitly
# supersede the Sep24 downloads on Oct2; do not mix display and CSV revisions.
wraw=json.loads((BASE/'sources'/'physical-waymo-selected.json').read_text())
source('waymo-csv','Waymo','CSV3 — Collision Counts and Comparison to Benchmarks, through June 2026',wraw['url'],'2026-10-02','Outcome=Any Injury; Benchmark Comparison=Any-injury-reported; Grouping Type=All Crashes')
source('waymo-notes','Waymo','Safety Impact Data Hub Release Notes','https://storage.googleapis.com/waymo-uploads/files/documents/safety/safety-impact-data/Waymo_Safety_Impact_Data_Hub_Release_Notes_20261002.pdf','2026-10-02','pp2–3 correction notice, benchmark year and county groupings; CSV3 data dictionary pp15–17')
wm=next(d for d in D if d['datasetId']=='physical-waymo-injury-rates')
wm['rows']=[]
chosen={'Los Angeles':('LA','US-CA-LosAngeles'),'Maricopa':('PHX','US-AZ-Maricopa'),'San Francisco Bay Area':('SF','US-CA-SFBay'),'Travis':('AUS','US-TX-Travis'),'Atlanta Area':('ATL','US-GA-AtlantaArea')}
for r in wraw['selectedRows']:
 if r['County Name'] not in chosen:continue
 key,geo=chosen[r['County Name']]
 for cohort,col in [('Waymo','Waymo'),('human benchmark','Benchmark')]:
  wm['rows'].append(row('injury-'+key+'-'+cohort,r['County Name']+' — '+cohort,float(r[col+' IPMM']),'crashed vehicles per million vehicle-miles','2020-09/2026-06' if cohort=='Waymo' else '2022 benchmark, spatially weighted to Waymo driving through 2026-06','waymo-csv','CSV3: Any Injury; Any-injury-reported; All Crashes; County Name='+r['County Name'],'95% intervals transcribed; human benchmark includes 32% underreporting correction. Observational comparison, not randomized.',geo,'estimated',cohort=cohort,ciLower=float(r[col+' IPMM CI Lower']),ciUpper=float(r[col+' IPMM CI Upper']),confidenceLevel=0.95,waymoCrashCount=int(r['Waymo Count'])))
wm['sources']=[S['waymo-csv'],S['waymo-notes'],S['waymo26']];wm['source']=S['waymo-csv'];wm['time'].update(observationStart='2020-09',observationEnd='2026-06',publishedAt='2026-10-02')
wm['unit']='crashed vehicles per million vehicle-miles';wm['metric']='Any-injury crashed-vehicle involvement rates, with source 95% confidence intervals'
wm['geography']['definition']='Provider operating domains within named counties. San Francisco Bay Area combines San Francisco, San Mateo and Santa Clara; Atlanta Area combines Fulton and DeKalb. Not entire-city coverage.'
wm['limitations']=['Current linked CSV values differ from some dashboard HTML point estimates; use this Oct2 corrected CSV consistently.','95% source Poisson intervals are preserved; estimates are observational, provider-reported and geographically weighted.','2022 human benchmark is not contemporaneous with all Waymo exposure; 32% injury underreporting correction is source applied.','Cannot generalize to other systems, all roads or snow; source notes residual time-of-day confounding.']
wm['uncertainty']=' '.join(wm['limitations']);wm['columns'].update(ciLower='Source lower 95% confidence limit in same unit',ciUpper='Source upper 95% confidence limit in same unit',confidenceLevel='0.95 from source method',waymoCrashCount='Source Waymo count for each location; repeated across paired rows, do not sum duplicates',cohort='Waymo or spatially weighted human benchmark');wm['fields']=wm['columns']
wm['transform'].update(type='scripted',description='Filter downloaded CSV3 by exact outcome, benchmark and grouping; retain five nonoverlapping service-area aggregates, all point estimates and intervals. No aggregate plus county double counting.',codePath='research/scripts/physical-complete.py',inputReferences=['research/sources/physical-waymo-selected.json',wraw['url']],validation='1804 raw CSV rows; 11 matching selected rows; five nonoverlapping areas yield ten cohort rows. Asserted intervals bracket estimates.')
wm['verification'].update(checkedRows=[r['id'] for r in wm['rows']],evidencePaths=['research/sources/physical-waymo-selected.json','research/sources/physical-verification.json'])
for r in wm['rows']:assert r['ciLower']<=r['value']<=r['ciUpper']
write(wm)
